import {createAdminClient,authenticateUser} from '../_shared/amazon/supabase.ts';
import {shopifyAccountCredentials,shopifyStoredApplicationCredentials,shopifyError} from '../_shared/shopifyAuth.ts';
import {confirmShopifyShipment} from '../_shared/shopifyShipment.ts';
const cors={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'authorization, x-client-info, apikey, content-type','Access-Control-Allow-Methods':'POST, OPTIONS'};
const response=(data:unknown,status=200)=>new Response(JSON.stringify(data),{status,headers:{...cors,'Content-Type':'application/json'}});
async function confirm(admin:any,ownerId:string,orderId:string){
 const found=await admin.from('fulfillment_orders').select('*').eq('id',orderId).eq('owner_id',ownerId).maybeSingle();
 if(found.error)throw found.error;const order=found.data;if(!order)throw new Error('Pedido no encontrado.');
 if(order.source_channel!=='shopify')return {status:'not_applicable'};
 if(!order.label_created_at||!order.tracking_number)throw new Error('La etiqueta no tiene seguimiento guardado. Activa guardar seguimiento para confirmar Shopify.');
 if(order.shopify_tracking_synced_at&&order.shopify_tracking_synced_number===order.tracking_number)return {status:'already_synced'};
 const lease=crypto.randomUUID();
 const claim=await admin.rpc('integration_shopify_claim_shipment',{p_order_id:orderId,p_owner_id:ownerId,p_lease:lease});
 if(claim.error)throw claim.error;const current=claim.data?.[0];if(!current)throw new Error('La confirmación Shopify ya está en curso.');
 try{
  const account=await admin.from('integration_accounts').select('*').eq('id',current.source_integration_account_id).eq('owner_id',ownerId).eq('provider','shopify').eq('enabled',true).neq('status','disabled').maybeSingle();
  if(account.error)throw account.error;if(!account.data)throw new Error('La cuenta Shopify del pedido está desconectada.');
  const c=await shopifyAccountCredentials(admin,account.data,await shopifyStoredApplicationCredentials(admin,ownerId));
  const deadline=Date.now()+120000;
  const request=async(query:string,variables:any)=>{
   if(Date.now()>=deadline)throw new Error('Shopify tardó demasiado. La confirmación se reintentará.');
   const res=await fetch(`https://${c.shopDomain}/admin/api/${c.apiVersion}/graphql.json`,{method:'POST',headers:{'Content-Type':'application/json','X-Shopify-Access-Token':c.accessToken},body:JSON.stringify({query,variables}),signal:AbortSignal.timeout(Math.min(20000,deadline-Date.now()))});
   const payload=await res.json().catch(()=>({}));
   if(!res.ok||payload.errors?.length){const message=payload.errors?.map((e:any)=>e.message).join(' · ')||`Shopify (${res.status})`;throw new Error(/access denied|access scope/i.test(message)?'Faltan permisos Shopify: read_merchant_managed_fulfillment_orders y write_merchant_managed_fulfillment_orders. Actualiza la app y vuelve a conectar la tienda.':message);}
   return payload.data;
  };
  const previous=await admin.from('order_cancellation_operations').select('details').eq('owner_id',ownerId).eq('order_id',orderId).eq('kind','label').eq('status','confirmed').order('created_at',{ascending:false}).limit(1);if(previous.error)throw previous.error;
  const result=await confirmShopifyShipment(request,{orderId:current.order_id,number:current.tracking_number,company:current.carrier_name||current.carrier_code||'Transportista',url:current.tracking_url,previousNumber:previous.data?.[0]?.details?.trackingNumber});
  const now=new Date().toISOString();
  const saved=await admin.from('fulfillment_orders').update({shopify_tracking_synced_at:now,shopify_tracking_synced_number:current.tracking_number,shopify_tracking_sync_error:null,source_status:'shipped',fulfilled_at:current.fulfilled_at||now}).eq('id',orderId).eq('owner_id',ownerId).eq('shopify_tracking_lease',lease).eq('tracking_number',current.tracking_number);
  if(saved.error)throw saved.error;return result;
 }catch(error){
  const saved=await admin.from('fulfillment_orders').update({shopify_tracking_sync_error:shopifyError(error)}).eq('id',orderId).eq('owner_id',ownerId).eq('shopify_tracking_lease',lease);if(saved.error)console.error('No se pudo guardar la incidencia Shopify.');throw error;
 }finally{await admin.from('fulfillment_orders').update({shopify_tracking_lease:null,shopify_tracking_lease_until:null}).eq('id',orderId).eq('owner_id',ownerId).eq('shopify_tracking_lease',lease);}
}
Deno.serve(async(req:Request)=>{
 if(req.method==='OPTIONS')return new Response('ok',{headers:cors});if(req.method!=='POST')return response({error:'Método no permitido.'},405);
 try{
  const admin=createAdminClient(),caller=await authenticateUser(req,admin);
  if(caller.role!=='admin'&&!caller.permissions?.includes('orders'))return response({error:'No tienes permiso para gestionar pedidos.'},403);
  const body=await req.json().catch(()=>({}));
  if(body.action==='retry_pending'){
   const rule=await admin.from('automation_rules').select('enabled,config').eq('owner_id',caller.data_owner_id).eq('rule_key','order_label_created').maybeSingle();if(rule.error)throw rule.error;
   if(rule.data&&(rule.data.enabled===false||rule.data.config?.pushToMarketplace===false||rule.data.config?.retryConfirmation===false||rule.data.config?.saveTracking===false))return response({ok:true,retried:0});
   const pending=await admin.rpc('integration_shopify_pending_shipments',{p_owner_id:caller.data_owner_id});
   if(pending.error)throw pending.error;const results=[];
   for(const row of (pending.data||[]).filter((r:any)=>!r.shopify_tracking_synced_at||r.shopify_tracking_synced_number!==r.tracking_number).slice(0,5)){try{results.push({orderId:row.id,...await confirm(admin,caller.data_owner_id,row.id)})}catch(error){results.push({orderId:row.id,error:shopifyError(error)})}}
   return response({ok:true,retried:results.length,results});
  }
  if(body.action!=='confirm_order_tracking')return response({error:'Acción no válida.'},400);
  return response({ok:true,...await confirm(admin,caller.data_owner_id,String(body.orderId||''))});
 }catch(error){const message=shopifyError(error);return response({error:message},/Sesión no válida/.test(message)?401:500);}
});

import { createClient } from 'npm:@supabase/supabase-js@2';

export type AppCaller={
  user_id:string;
  data_owner_id:string;
  role:string;
  active:boolean;
  permissions:string[]|null;
};

export function getAdminKey(){
  const secretKeys=Deno.env.get('SUPABASE_SECRET_KEYS');
  if(secretKeys){
    try{
      const parsed=JSON.parse(secretKeys);
      if(typeof parsed?.default==='string'&&parsed.default.trim())return parsed.default.trim();
    }catch{/* legacy fallback below */}
  }
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}

export function createAdminClient(){
  const url=(Deno.env.get('SUPABASE_URL')||'').trim();
  const key=getAdminKey();
  if(!url||!key)throw new Error('Configuración interna de Supabase no disponible.');
  return createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
}

export function requireInternalSecret(req:Request){
  const expected=getAdminKey();
  const presented=(req.headers.get('apikey')||'').trim();
  if(!expected||!presented||presented!==expected)throw new Error('Llamada interna no autorizada.');
}

export async function authenticateUser(req:Request,admin:any):Promise<AppCaller>{
  const token=(req.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'').trim();
  if(!token)throw new Error('Sesión no válida.');
  const {data:userData,error:userError}=await admin.auth.getUser(token);
  if(userError||!userData?.user)throw new Error('Sesión no válida.');
  const {data:caller,error}=await admin.from('app_users')
    .select('user_id,data_owner_id,role,active,permissions')
    .eq('user_id',userData.user.id)
    .maybeSingle();
  if(error)throw error;
  if(!caller?.active)throw new Error('Tu acceso está desactivado.');
  const {data:workspace,error:workspaceError}=await admin.from('workspaces').select('status').eq('id',caller.data_owner_id).maybeSingle();
  if(workspaceError)throw workspaceError;
  if(!workspace||!['active','trialing'].includes(workspace.status))throw new Error('El acceso de tu empresa está suspendido.');
  return caller as AppCaller;
}

export async function authenticateAdminUser(req:Request,admin:any){
  const caller=await authenticateUser(req,admin);
  if(caller.role!=='admin')throw new Error('Solo un administrador puede iniciar una sincronización manual de Amazon.');
  return caller;
}

export function shopifyError(error:unknown,fallback='No se pudo completar la conexión con Shopify.'):string{
  if(typeof error==='string'&&error.trim()&&error!=='[object Object]')return error.trim();
  if(error&&typeof error==='object'){
    const value=error as Record<string,unknown>;
    for(const key of ['message','error','error_description','details']){
      if(value[key]&&value[key]!==error){const detail=shopifyError(value[key],'');if(detail)return detail;}
    }
  }
  return fallback;
}

export function shopifyDomain(value:unknown){
  const domain=String(value??'').trim().toLowerCase().replace(/^https:\/\//,'').replace(/\/$/,'');
  if(!/^[a-z0-9][a-z0-9-]*\.myshopify\.com$/.test(domain))throw new Error('Indica el dominio permanente de Shopify: tienda.myshopify.com, sin rutas.');
  return domain;
}

export function shopifyLegacyCredentials(domain:unknown,accessToken:unknown){
  const token=String(accessToken??'').trim();
  if(!token)throw new Error('Indica el access token de la app antigua.');
  return {shopDomain:shopifyDomain(domain),accessToken:token,authMode:'token'};
}

export function shopifyApplicationCredentials(environment:any,configured:any){
  const candidate=environment?.clientId&&environment?.clientSecret?environment:configured;
  const clientId=String(candidate?.clientId||'').trim(),clientSecret=String(candidate?.clientSecret||'').trim();
  return {clientId,clientSecret,ready:Boolean(clientId&&clientSecret)};
}

export async function shopifyStoredApplicationCredentials(admin:any,ownerId:string){
  const environment={clientId:Deno.env.get('SHOPIFY_CLIENT_ID')||'',clientSecret:Deno.env.get('SHOPIFY_CLIENT_SECRET')||''};
  let configured={};
  if(!environment.clientId||!environment.clientSecret){
    const result=await admin.rpc('integration_read_named_secret',{p_name:`shopify-app:${ownerId}`});
    if(result.error)throw result.error;
    try{configured=JSON.parse(result.data||'{}')}catch{}
  }
  return shopifyApplicationCredentials(environment,configured);
}

export async function shopifyHash(value:string){
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))).map(v=>v.toString(16).padStart(2,'0')).join('');
}

export async function verifyShopifyCallback(params:URLSearchParams,secret:string){
  const keys=[...params.keys()];
  if(new Set(keys).size!==keys.length)return false;
  const supplied=params.get('hmac')||'';
  if(!/^[a-f0-9]{64}$/.test(supplied))return false;
  const message=[...params.entries()].filter(([key])=>key!=='hmac').sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>`${k}=${v}`).join('&');
  const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['verify']);
  const signature=new Uint8Array(supplied.match(/../g)!.map(v=>parseInt(v,16)));
  return crypto.subtle.verify('HMAC',key,signature,new TextEncoder().encode(message));
}

export async function shopifyTokenRequest(domain:string,body:URLSearchParams){
  const res=await fetch(`https://${shopifyDomain(domain)}/admin/oauth/access_token`,{
    method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',Accept:'application/json'},body,
    redirect:'error',signal:AbortSignal.timeout(20000),
  });
  const token=await res.json().catch(()=>({}));
  if(!res.ok||token.error)throw new Error(token.error==='invalid_client'?'Shopify no acepta el ID o secreto de la app. Comprueba sus credenciales.':token.error==='shop_not_permitted'?'La app y la tienda deben pertenecer a la misma organización Shopify. Para tiendas de clientes utiliza Autorizar con Shopify.':token.error==='invalid_grant'?'Shopify ha caducado o revocado la autorización. Vuelve a conectar la tienda.':`Shopify (${res.status}): no se pudo obtener la autorización. Comprueba que la app esté instalada y tenga permiso read_orders.`);
  return token;
}

export function shopifyTokenCredentials(stored:any,token:any,now=Date.now()){
  if(!token?.access_token)throw new Error('Shopify no devolvió un access token.');
  const grantedScopes=new Set(String(token.scope||'').split(/[\s,]+/).filter(Boolean));
  if(!grantedScopes.has('read_orders')&&!grantedScopes.has('write_orders'))throw new Error('La app necesita permiso read_orders o write_orders. Añádelo en Shopify y vuelve a autorizar.');
  if(token.expires_in!=null&&(!Number.isFinite(Number(token.expires_in))||Number(token.expires_in)<=0))throw new Error('Shopify devolvió una caducidad no válida.');
  return {...stored,accessToken:String(token.access_token),scope:String(token.scope),expiresAt:token.expires_in?now+Number(token.expires_in)*1000:null,...(token.refresh_token?{refreshToken:String(token.refresh_token)}:{})};
}

export async function resolveShopifyCredentials(stored:any,config:any,request=shopifyTokenRequest,persist?: (stored:any)=>Promise<unknown>){
  const domain=shopifyDomain(stored.shopDomain||stored.shop_domain||config.shopDomain);
  let token=String(stored.accessToken||stored.access_token||'').trim();
  if(!token||(stored.expiresAt&&Number(stored.expiresAt)<=Date.now()+300000)){
    const clientId=stored.clientId||Deno.env.get('SHOPIFY_CLIENT_ID');
    const clientSecret=stored.clientSecret||Deno.env.get('SHOPIFY_CLIENT_SECRET');
    if(!clientId||!clientSecret)throw new Error('Renueva la conexión con Shopify desde Integraciones.');
    const fields:Record<string,string>={client_id:clientId,client_secret:clientSecret};
    if(stored.authMode==='client_credentials')fields.grant_type='client_credentials';
    else if(stored.refreshToken){fields.grant_type='refresh_token';fields.refresh_token=stored.refreshToken;}
    else throw new Error('Renueva la autorización de Shopify desde Integraciones.');
    const renewed=shopifyTokenCredentials(stored,await request(domain,new URLSearchParams(fields)));
    if(persist)await persist(renewed);
    token=renewed.accessToken;
  }
  return {shopDomain:domain,accessToken:token,apiVersion:String(config.apiVersion||'2026-07')};
}

export async function shopifyAccountCredentials(admin:any,account:any,appCredentials?:{clientId:string;clientSecret:string}){
  async function read(){
    const result=await admin.from('integration_accounts').select('*').eq('id',account.id).eq('owner_id',account.owner_id).maybeSingle();
    if(result.error)throw result.error;
    if(!result.data?.enabled||result.data.status==='disabled')throw new Error('La cuenta Shopify está desconectada.');
    const secret=await admin.rpc('integration_read_secret',{p_secret_id:result.data.secret_id});
    if(secret.error)throw secret.error;
    return {row:result.data,stored:JSON.parse(secret.data||'{}')};
  }
  let current=await read();
  if(current.stored.accessToken&&(!current.stored.expiresAt||current.stored.expiresAt>Date.now()+300000))return resolveShopifyCredentials(current.stored,current.row.config||{});
  const lease=crypto.randomUUID();
  let claimed=false;
  for(let attempt=0;attempt<125;attempt++){
    const result=await admin.rpc('integration_shopify_claim_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease});
    if(result.error)throw result.error;
    if(result.data){claimed=true;break;}
    await new Promise(resolve=>setTimeout(resolve,200));
    current=await read();
    if(current.stored.accessToken&&(!current.stored.expiresAt||current.stored.expiresAt>Date.now()+300000))return resolveShopifyCredentials(current.stored,current.row.config||{});
  }
  if(!claimed)throw new Error('Shopify está renovando la autorización. Vuelve a intentarlo en unos segundos.');
  try{
    current=await read();
    if(current.stored.authMode==='oauth'&&appCredentials&&current.stored.clientId!==appCredentials.clientId)throw new Error('La app Shopify cambió. Vuelve a autorizar esta tienda.');
    const storedForRenewal=current.stored.authMode==='oauth'&&appCredentials?{...current.stored,clientSecret:appCredentials.clientSecret}:current.stored;
    return await resolveShopifyCredentials(storedForRenewal,current.row.config||{},shopifyTokenRequest,async stored=>{
      if(current.stored.authMode==='oauth')delete stored.clientSecret;
      const result=await admin.rpc('integration_shopify_commit_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease,p_version:current.row.shopify_credential_version,p_secret:JSON.stringify(stored)});
      if(result.error)throw result.error;
      if(!result.data)throw new Error('La conexión de Shopify cambió durante la renovación. Vuelve a intentarlo.');
    });
  }finally{
    await admin.rpc('integration_shopify_release_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease});
  }
}

export async function commitShopifyAuthorization(admin:any,account:any,pending:any,stored:any){
  const config={...(account.config||{}),shopDomain:stored.shopDomain,authMode:'oauth',syncOrders:pending.syncOrders!==false,apiVersion:'2026-07'};
  delete config.oauthStateHash;
  const result=await admin.rpc('integration_shopify_complete_oauth',{p_account_id:account.id,p_owner_id:account.owner_id,p_version:account.shopify_credential_version,p_secret:JSON.stringify(stored),p_display_name:pending.displayName||account.display_name,p_config:config});
  if(result.error)throw result.error;
  if(!result.data)throw new Error('La conexión de Shopify cambió mientras autorizabas. Vuelve a conectar la tienda.');
}

export async function confirmShopifyShipment(request:(query:string,variables:any)=>Promise<any>,shipment:{orderId:string;number:string;company:string;url?:string|null;previousNumber?:string|null}){
  if(!/^gid:\/\/shopify\/Order\/\d+$/.test(shipment.orderId)||!shipment.number.trim())throw new Error('Falta el pedido Shopify o el seguimiento.');
  const trackingInfo:any={number:shipment.number.trim(),company:shipment.company.trim()||'Transportista'};
  if(shipment.url){const url=new URL(shipment.url);if(!['https:','http:'].includes(url.protocol))throw new Error('Enlace de seguimiento no válido.');trackingInfo.url=url.href;}
  const fulfillmentOrders:any[]=[];let after:string|null=null,remote:any=null;
  do{
    const data=await request(`query ZenviaShipmentOrder($id:ID!,$after:String){order(id:$id){id cancelledAt fulfillments(first:250){id status trackingInfo(first:10){number}} fulfillmentOrders(first:100,after:$after){nodes{id status supportedActions{action}} pageInfo{hasNextPage endCursor}}}}`,{id:shipment.orderId,after});
    remote=data?.order;if(!remote)throw new Error('Pedido Shopify no encontrado.');
    if(remote.cancelledAt)throw new Error('El pedido Shopify está cancelado.');
    fulfillmentOrders.push(...(remote.fulfillmentOrders?.nodes||[]));
    after=remote.fulfillmentOrders?.pageInfo?.hasNextPage?remote.fulfillmentOrders.pageInfo.endCursor:null;
    if(fulfillmentOrders.length>1000)throw new Error('Demasiadas órdenes de preparación en Shopify.');
  }while(after);
  const existing=(remote.fulfillments||[]).filter((f:any)=>f.status==='SUCCESS'&&(f.trackingInfo||[]).some((t:any)=>t.number===trackingInfo.number));
  if((remote.fulfillments||[]).length>=250)throw new Error('Revisa manualmente los envíos de este pedido Shopify.');
  if(shipment.previousNumber){
    const replacements=(remote.fulfillments||[]).filter((f:any)=>f.status==='SUCCESS'&&(f.trackingInfo||[]).some((t:any)=>t.number===shipment.previousNumber));
    if(replacements.length||existing.length){
      const ids=existing.map((f:any)=>f.id);
      for(const previous of replacements){
      const result=await request(`mutation ZenviaReplaceTracking($id:ID!,$tracking:FulfillmentTrackingInput!){fulfillmentTrackingInfoUpdate(fulfillmentId:$id,trackingInfoInput:$tracking,notifyCustomer:true){fulfillment{id} userErrors{field message}}}`,{id:previous.id,tracking:trackingInfo});
      const payload=result.fulfillmentTrackingInfoUpdate;if(payload?.userErrors?.length)throw new Error(payload.userErrors.map((e:any)=>e.message).join(' · '));if(!payload?.fulfillment?.id)throw new Error('Shopify no confirmó el nuevo seguimiento.');
      ids.push(payload.fulfillment.id);
      }
      return {fulfillmentIds:ids,status:replacements.length?'confirmed':'already_synced'};
    }
  }
  const groups=new Map<string,any[]>();
  for(const fo of fulfillmentOrders){
    if(['CLOSED','CANCELLED'].includes(fo.status))continue;
    if(!(fo.supportedActions||[]).some((a:any)=>a.action==='CREATE_FULFILLMENT'))throw new Error('Shopify no permite preparar este pedido en su estado actual.');
    // One fulfillment order per mutation is valid across all assigned locations.
    const location=fo.id;
    const items:any[]=[];let cursor:string|null=null;
    do{
      const data=await request(`query ZenviaShipmentItems($id:ID!,$after:String){fulfillmentOrder(id:$id){lineItems(first:100,after:$after){nodes{id remainingQuantity} pageInfo{hasNextPage endCursor}}}}`,{id:fo.id,after:cursor});
      const connection=data?.fulfillmentOrder?.lineItems;if(!connection)throw new Error('No se pudieron consultar las cantidades pendientes de Shopify.');
      for(const item of connection.nodes||[])if(item.remainingQuantity>0)items.push({id:item.id,quantity:item.remainingQuantity});
      cursor=connection.pageInfo?.hasNextPage?connection.pageInfo.endCursor:null;
      if(items.length>10000)throw new Error('Demasiadas líneas en el pedido Shopify.');
    }while(cursor);
    if(items.length){const group=groups.get(location)||[];group.push({fulfillmentOrderId:fo.id,fulfillmentOrderLineItems:items});groups.set(location,group);}
  }
  if(!groups.size&&!existing.length)throw new Error('El pedido Shopify no tiene cantidades pendientes para este envío.');
  const ids=existing.map((f:any)=>f.id);
  for(const lineItemsByFulfillmentOrder of groups.values()){
    const result=await request(`mutation ZenviaShipmentCreate($fulfillment:FulfillmentInput!){fulfillmentCreate(fulfillment:$fulfillment){fulfillment{id} userErrors{field message}}}`,{fulfillment:{notifyCustomer:true,trackingInfo,lineItemsByFulfillmentOrder}});
    const payload=result?.fulfillmentCreate;
    if(payload?.userErrors?.length)throw new Error(payload.userErrors.map((e:any)=>e.message).join(' · '));
    if(!payload?.fulfillment?.id)throw new Error('Shopify no confirmó la creación del envío.');
    ids.push(payload.fulfillment.id);
  }
  return {fulfillmentIds:ids,status:groups.size?'confirmed':'already_synced'};
}

export function preserveShopifyLabelTracking(rows:any[],existing:any[]){
 const local=new Map(existing.filter(row=>row.label_created_at||row.label_cancelled_at).map(row=>[row.sendcloud_id,row]));
 return rows.map(row=>{
  const saved:any=local.get(row.sendcloud_id);if(!saved)return row;
  const result={...row};
  if(saved.label_cancelled_at&&!saved.label_created_at){for(const key of ['tracking_number','tracking_url','tracking_status_code','tracking_status_message','tracking_updated_at','fulfilled_at'])result[key]=null;return result;}
  for(const key of ['tracking_number','tracking_url','carrier_name','tracking_status_code','tracking_status_message','tracking_updated_at','fulfilled_at'])result[key]=saved[key]??row[key];
  if(saved.raw_payload?._zenvia_tracking)result.raw_payload={...row.raw_payload,_zenvia_tracking:saved.raw_payload._zenvia_tracking};
  return result;
 });
}
